# -*- coding: utf-8 -*-
"""Lecture 26 vignette pool C -- Venous Disorders: superficial phlebitis and
thrombophlebitis (including septic), arteriovenous fistula of the extremity, and
mixed cases that make the student choose among the venous conditions.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation.

Patient vignettes with a varied lead-in (the lead-in decides the answer).
Deck facts only (slides 47, 51, 53-57, 74-86, plus 27-32 for the mixed cases).
Two things are keyed on the recording's emphasis but stated on the slides in
general terms: a healthy fistula carries a thrill and soft bruit (s83), so a
fistula that has lost both is not healthy and goes to the specialist.
Wells scores in stems are 2 (moderate) and 3 (high), never 0.
No acronyms anywhere: every term is written out.
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5l26_scope import *


def S(topic, io, q, opts, cite, slot):
    d = Q(topic, io, q, opts, cite); d["slot"] = slot; return d


def V(topic, io, q, opts, cite, slot, lead):
    d = S(topic, io, q, opts, cite, slot); d["lead"] = lead; return d


PHL = "Superficial phlebitis and thrombophlebitis"
AVF = "Arteriovenous fistula of the extremity"
MIX = "Venous disorders, mixed cases"

